namespace EnterpriseKnowledgeAgent.Application.Storage;

/// <summary>
/// TASK-S3-01: private object storage abstraction backing the source-files
/// bucket (ASDD §11.1, §11.2). Keys are always server-generated by
/// <see cref="ObjectKeyFactory"/> (TASK-S3-02) - callers never accept a
/// client-supplied key. Implementations must never expose public ACLs.
/// </summary>
public interface IObjectStorage
{
    /// <summary>Uploads (or overwrites) the object at <paramref name="key"/>.</summary>
    Task PutAsync(string key, Stream content, string contentType, CancellationToken cancellationToken = default);

    /// <summary>Opens a stream to read the object's bytes. Throws <see cref="ObjectNotFoundException"/> if it does not exist.</summary>
    Task<Stream> GetAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Deletes the object at <paramref name="key"/>. Idempotent - succeeds even if the object does not exist (TASK-S3-04).</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Returns whether an object exists at <paramref name="key"/>.</summary>
    Task<bool> ExistsAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Lightweight readiness probe (bucket head/list) used by health checks (TASK-S3-04, module 31).</summary>
    Task<ObjectStorageHealth> CheckHealthAsync(CancellationToken cancellationToken = default);
}
